<template>
    <div class="p-6">
      <div class="flex justify-between items-center mb-6">
        <h1 class="text-2xl font-bold">Pages</h1>
        <router-link
          to="/admin/pages/create"
          class="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700"
        >
          + Add New
        </router-link>
      </div>
  
      <table class="w-full border bg-white rounded shadow-sm text-sm">
        <thead class="bg-gray-100">
          <tr>
            <th class="p-3 text-left">Title</th>
            <th class="p-3 text-center">Status</th>
            <th class="p-3 text-center">Date</th>
            <th class="p-3 text-right">Actions</th>
          </tr>
        </thead>
        <tbody>
          <tr
            v-for="page in pages"
            :key="page.id"
            class="border-t hover:bg-gray-50 transition"
          >
            <td class="p-3 font-medium">
              <router-link :to="`/admin/pages/${page.id}`" class="hover:underline">
                {{ page.title }}
              </router-link>
            </td>
            <td class="p-3 text-center capitalize">{{ page.status }}</td>
            <td class="p-3 text-center">{{ formatDate(page.createdAt) }}</td>
            <td class="p-3 text-right space-x-2">
            <router-link
                :to="`/admin/pages/${page.id}`"
                class="text-blue-600 hover:underline"
            >
                Edit
            </router-link>
            <button
                @click="deletePage(page.id)"
                class="text-red-600 hover:underline"
            >
                Delete
            </button>
            </td>
          </tr>
        </tbody>
      </table>
  
      <p v-if="pages.length === 0" class="text-center py-6 text-gray-500">
        No pages found.
      </p>
    </div>
  </template>
  
  <script>
  import axios from 'axios'
  import { API_ENDPOINTS } from '@/config/api'
  
  export default {
    data() {
      return {
        pages: [],
      }
    },
    methods: {
      formatDate(date) {
        return new Date(date).toLocaleDateString('id-ID', {
          year: 'numeric',
          month: 'short',
          day: 'numeric'
        })
      },
      async fetchPages() {
        try {
          const res = await axios.get(`${API_ENDPOINTS.posts}?type=page`)
          this.pages = res.data
        } catch (err) {
          console.error(err)
        }
      },
      async deletePage(id) {
    if (confirm('Are you sure you want to delete this page?')) {
      try {
        await axios.delete(`${API_ENDPOINTS.posts}/${id}`)
        this.fetchPages() // reload list
      } catch (err) {
        console.error('Failed to delete:', err)
      }
    }
  }

    },
    mounted() {
      this.fetchPages()
    }
  }
  </script>
  