<script>
import axios from 'axios'
import { API_ENDPOINTS } from '@/config/api'


export default {
  props: ['isOpen'],
  data() {
    return {
      dropdownOpen: '',
      subDropdownOpen: '',
      menus: []
    }
  },
  methods: {
    toggleDropdown(name) {
      this.dropdownOpen = this.dropdownOpen === name ? '' : name
      if (name !== 'konten') this.subDropdownOpen = ''
    },
    toggleSubDropdown(name) {
      this.subDropdownOpen = this.subDropdownOpen === name ? '' : name
    },
    closeDropdown() {
      this.dropdownOpen = ''
      this.subDropdownOpen = ''
    }
  },
  mounted() {
    axios.get(API_ENDPOINTS.menuList)
      .then(res => {
        this.menus = res.data
      })
      .catch(err => {
        console.error('Error fetching menus:', err)
      })
  }
}
</script>

