<template>
    <div class="p-6 space-y-4">
      <h1 class="text-2xl font-bold mb-4">
        {{ isEdit ? 'Edit Page' : 'Add New Page' }}
      </h1>
  
      <input
        v-model="form.title"
        placeholder="Title"
        class="w-full border p-2 rounded text-lg font-semibold"
        @input="generateSlug"
      />
  
      <textarea
        v-model="form.excerpt"
        placeholder="Excerpt"
        class="w-full p-2 border rounded"
        rows="2"
      ></textarea>
  
      <textarea
        v-model="form.content"
        placeholder="Content"
        class="w-full p-2 border rounded h-60"
      ></textarea>
  
      <select v-model="form.status" class="w-full border p-2 rounded">
        <option value="draft">Draft</option>
        <option value="published">Published</option>
      </select>
  
      <button
        @click="savePage"
        class="bg-green-600 hover:bg-green-700 text-white px-4 py-2 rounded"
      >
        {{ isEdit ? 'Update' : 'Publish' }}
      </button>
    </div>
  </template>
  
  <script>
  import axios from 'axios'
  import { API_ENDPOINTS } from '@/config/api'
  
  export default {
    data() {
      return {
        form: {
          title: '',
          slug: '',
          excerpt: '',
          content: '',
          status: 'draft',
          type: 'page',
          website_id: 1,
          user_id: 1
        },
        isEdit: false
      }
    },
    methods: {
      generateSlug() {
        this.form.slug = this.form.title
          .toLowerCase()
          .replace(/ /g, '-')
          .replace(/[^\w-]+/g, '')
      },
      async fetchPage(id) {
        try {
          const res = await axios.get(`${API_ENDPOINTS.posts}/${id}`)
          this.form = {
            ...res.data,
            type: 'page'
          }
          this.isEdit = true
        } catch (err) {
          console.error('Failed to fetch page:', err)
        }
      },
      async savePage() {
        try {
          if (this.isEdit) {
            await axios.put(`${API_ENDPOINTS.posts}/${this.$route.params.id}`, this.form)
          } else {
            await axios.post(API_ENDPOINTS.posts, this.form)
          }
          this.$router.push('/admin/pages')
        } catch (err) {
          console.error('Failed to save page:', err)
        }
      }
    },
    mounted() {
      const id = this.$route.params.id
      if (id) {
        this.fetchPage(id)
      }
    }
  }
  </script>
  