<template>
  <div class="p-6">
    <!-- Header -->
    <div class="flex justify-between items-center mb-4">
      <h1 class="text-xl font-bold">All Posts</h1>
      <router-link
        to="/admin/posts/create"
        class="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700"
      >
        + Add New
      </router-link>
    </div>

    <!-- Table -->
    <table class="min-w-full bg-white border" v-if="posts.length > 0">
      <thead>
        <tr>
          <th class="p-2 border text-left">Title</th>
          <th class="p-2 border text-left">Status</th>
          <th class="p-2 border text-left">Published At</th>
          <th class="p-2 border text-right">Actions</th>
        </tr>
      </thead>
      <tbody>
        <tr v-for="post in posts" :key="post.id">
          <td class="p-2 border">{{ post.title }}</td>
          <td class="p-2 border capitalize">{{ post.status }}</td>
          <td class="p-2 border">
            {{ post.published_at ? formatDate(post.published_at) : '-' }}
          </td>
          <td class="p-2 border text-right space-x-2">
            <router-link
              :to="`/admin/posts/${post.id}`"
              class="text-blue-600 hover:underline"
            >
              Edit
            </router-link>
            <button
              @click="deletePost(post.id)"
              class="text-red-600 hover:underline"
            >
              Delete
            </button>
          </td>
        </tr>
      </tbody>
    </table>

    <!-- No posts -->
    <div v-else class="text-center py-6 text-gray-500">
      No posts found.
    </div>
  </div>
</template>

<script>
import axios from 'axios'
import { API_ENDPOINTS } from '@/config/api'

export default {
  data() {
    return {
      posts: []
    }
  },
  methods: {
    async fetchPosts() {
      try {
        const res = await axios.get(`${API_ENDPOINTS.posts}?type=post`)
        this.posts = res.data
      } catch (err) {
        console.error('Failed to fetch posts:', err)
      }
    },
    async deletePost(id) {
      if (confirm('Delete this post?')) {
        try {
          await axios.delete(`${API_ENDPOINTS.posts}/${id}`)
          await this.fetchPosts()
        } catch (err) {
          console.error('Failed to delete post:', err)
          alert('Failed to delete. Please try again.')
        }
      }
    },
    formatDate(dateStr) {
      const date = new Date(dateStr)
      return date.toLocaleDateString('id-ID', {
        year: 'numeric',
        month: 'short',
        day: 'numeric'
      })
    }
  },
  mounted() {
    this.fetchPosts()
  }
}
</script>
